from typing import List, TypedDict

from langgraph.graph import END, START, StateGraph


class PilotState(TypedDict, total=False):
    items: List[str]
    ranked: List[str]


def collect(state: PilotState) -> PilotState:
    return {"items": list(state.get("items") or [])}


def verify(state: PilotState) -> PilotState:
    return {"items": [i for i in state.get("items", []) if i]}


def compose(state: PilotState) -> PilotState:
    return {"ranked": sorted(state.get("items", []))}


graph = StateGraph(PilotState)
graph.add_node("collect", collect)
graph.add_node("verify", verify)
graph.add_node("compose", compose)
graph.add_edge(START, "collect")
graph.add_edge("collect", "verify")
graph.add_edge("verify", "compose")
graph.add_edge("compose", END)
app = graph.compile()
